scwin.grid1_ongroupby = function(options) {
    options.groupbyHeader = [{
            inputType: "text",
            value: "header1"
        },
        {
            inputType: "text",
            value: "header2"
        },
        {
            inputType: "text",
            value: "header3"
        }
    ]
    options.groupbyFooter = [{
            inputType: "text",
            value: "footer1"
        },
        {
            inputType: "text",
            value: "footer2"
        },
        {
            inputType: "text",
            value: "footer3"
        },
    ];
    this.groupby(options);
    return false;
}
scwin.trigger1_onclick = function() {
    console.log('search');
    scwin.data1 = [
        "0", "A", 1,
        "0", "A", 2,
        "0", "A", 3,
        "0", "B", 4,
        "0", "B", 5,
        "0", "B", 6,
        "1", "B", 7,
        "1", "C", 8,
        "1", "C", 9,
        "1", "C", 10,
        "1", "C", 11
    ];
    dataList1.setData(scwin.data1.slice(0));
};
scwin.grid1_groupbyFilterBoxFormatter = function(f) {
    console.log(JSON.stringify(f));
}
scwin.grid1_oncellclick = function(row, col) {
    console.log('row : ' + row);
    dataList1.setCellData(row, 'col3', '9999');
    console.log(dataList1.getCellData(row, 'col3'));
}
scwin.formatter = function(data) {
    console.log(data);
};
scwin.trigger2_onclick = function(e) {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.isIE = function() {
    return window.document.documentMode ? window.document.documentMode : false;
}
scwin.__isCheckColor = function() {
    if (scwin.isIE()) {
        return WebSquare.wUnit.getJq("#grid1_cell_1_0").css("color") == "rgb(255, 0, 0)" && WebSquare.wUnit.getJq("#grid1_cell_1_1").css("color") == "rgb(255, 0, 0)" && WebSquare.wUnit.getJq("#grid1_cell_1_2").css("color") == "rgb(255, 0, 0)";
    } else {
        return WebSquare.wUnit.getJq("#grid1_cell_6_0").css("color") == "rgb(0, 0, 0)" && WebSquare.wUnit.getJq("#grid1_cell_6_1").css("color") == "rgb(0, 0, 0)" && WebSquare.wUnit.getJq("#grid1_cell_6_2").css("color") == "rgb(0, 0, 0)" || (WebSquare.wUnit.getJq("#grid1_cell_6_0").css("color") == "rgb(255, 0, 0)" && WebSquare.wUnit.getJq("#grid1_cell_6_1").css("color") == "rgb(255, 0, 0)" && WebSquare.wUnit.getJq("#grid1_cell_6_2").css("color") == "rgb(255, 0, 0)");
    }
}
scwin.checkSimulate1 = function() {
    scwin.simulateWrapper('#grid1_column5', 'drag-n-drop', {
        dx: -10,
        dy: -50
    });
}
scwin.checkSimulate2 = function() {
    scwin.simulateWrapper('#grid1_column3', 'drag-n-drop', {
        dx: -10,
        dy: -50
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 "조회"버튼을 클릭한다.
    //1. After running the sample, click the "Query" button.
    //Verify step 1. The data is retrieved and the data in row 0,1,2 (including the "A" value) is shown in red.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_0').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_1').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_2').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_1_0').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_1_1').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_1_2').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_0').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_1').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_2').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. '분류1'항목을 groupby 시킨다.
    //2. Groupby the 'Category 1' item.
    //Verify step 2. Grouped by 'Category 1' and only 'A' is shown in red (Previously the 'B' value is also shown in red)
    WebSquare.wUnit.addCommand("set", "scwin.checkSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_0').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_1').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_2').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_3_0').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_3_1').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_3_2').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__isCheckColor()", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_4_0').css('color') == 'rgb(0, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_4_1').css('color') == 'rgb(0, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_4_2').css('color') == 'rgb(0, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_5_0').css('color') == 'rgb(0, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_5_1').css('color') == 'rgb(0, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_5_2').css('color') == 'rgb(0, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_9_0').css('color') == 'rgb(0, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_9_1').css('color') == 'rgb(0, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_9_2').css('color') == 'rgb(0, 0, 0)'", "true");
    //Test step 3. '분류2'항목을 groupby 시킨다.
    //3. Make the 'Category 2' item groupby.
    //Verify step 3. It is groupby with 'Category 2' and only 'A' is shown in red (Previously, 'B' value also appears red)
    WebSquare.wUnit.addCommand("set", "scwin.checkSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_0').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_1').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_2').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_3_0').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_3_1').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_3_2').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_4_0').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_4_1').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_4_2').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_7_0').css('color') == 'rgb(0, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_7_1').css('color') == 'rgb(0, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_7_2').css('color') == 'rgb(0, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_8_0').css('color') == 'rgb(0, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_8_1').css('color') == 'rgb(0, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_8_2').css('color') == 'rgb(0, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_9_0').css('color') == 'rgb(0, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_9_1').css('color') == 'rgb(0, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_9_2').css('color') == 'rgb(0, 0, 0)'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //formatter
    window.testFunc = function(data, fdata, row, col) {
        if (fdata == "A") {
            grid1.setRowColor(row, "red");
        }
        return data;
    };
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 30-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
